"use client";

import { useState, useEffect } from "react";
import { useFinanceData } from "@/lib/api";
import { Card, Skeleton, FormModal } from "@/components/finance";
import { useSubmit } from "@/lib/api";

const LearningPage = () => {
  const { data: topics, isLoading, isError, refetch } = useFinanceData<{ id: number; title: string }[]>("/learning/topics");
  const { data: selectedTopic, isLoading: selectedTopicLoading, isError: selectedTopicError, refetch: selectedTopicRefetch } = useFinanceData<{ content: string }>(`/learning/topic/1`);
  const { data: personalizedLessons, isLoading: personalizedLessonsLoading, isError: personalizedLessonsError, refetch: personalizedLessonsRefetch } = useFinanceData<{ content: string }[]>(`/learning/personalized`);

  if (isLoading || selectedTopicLoading || personalizedLessonsLoading) return <Skeleton />;
  if (isError || selectedTopicError || personalizedLessonsError) return <div>Error loading data</div>;

  return (
    <div className="flex flex-col h-full">
      <div className="flex-1">
        <div className="flex flex-col h-full">
          <div className="flex-1 overflow-y-auto">
            {topics && topics.map(topic => (
              <Card key={topic.id} title={topic.title} onClick={() => selectedTopicRefetch()} />
            ))}
          </div>
        </div>
      </div>
      <div className="flex-1">
        <div className="flex flex-col h-full">
          <div className="flex-1 overflow-y-auto">
            {selectedTopic && <div dangerouslySetInnerHTML={{ __html: selectedTopic.content }} />}
          </div>
        </div>
      </div>
      <div className="flex-1">
        <div className="flex flex-col h-full">
          <div className="flex-1 overflow-y-auto">
            {personalizedLessons && personalizedLessons.map(lesson => (
              <Card key={lesson.id} title={lesson.content} onClick={() => personalizedLessonsRefetch()} />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default LearningPage;
